const body = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};

// Provider identification — providers must include provider in payload, or we
// try to infer from the URL scheme in the QR-like id, or fall back to a header.
const providerCode = (
  body.provider ||
  headers['x-evw-provider'] ||
  (Array.isArray(body.rates) && body.rates[0] && body.rates[0].provider) ||
  'unknown'
).toLowerCase();
const allowed = ['hkev','clp','shell','tesla'];
if (!allowed.includes(providerCode)) {
  throw new Error('rate-normalize: unknown provider "' + providerCode + '"');
}

// Accept either:
//   { provider, station_external_id, poles: [ {external_id, hourly_rates: [...]} ] }
//   { provider, rates: [ {station_external_id, pole_external_id, day_of_week, hour_start_local, ...} ] }
const out = [];

if (Array.isArray(body.poles)) {
  for (const p of body.poles) {
    const poleExt = String(p.external_id || p.pole_id || p.id);
    const stationExt = String(body.station_external_id || p.station_external_id || '');
    if (!poleExt || !stationExt) continue;
    for (const r of (p.hourly_rates || p.rates || [])) {
      out.push({
        station_external_id: stationExt,
        pole_external_id: poleExt,
        provider_code: providerCode,
        day_of_week: Number.isInteger(r.day_of_week) ? r.day_of_week : 0,
        hour_start_local: r.hour_start_local || r.hour || '00:00:00',
        price_per_kwh_hkd: String(r.price_per_kwh_hkd ?? r.price ?? 0),
        parking_fee_hkd: String(r.parking_fee_hkd ?? 0),
        valid_from: r.valid_from || new Date().toISOString(),
        valid_to: r.valid_to || null
      });
    }
  }
} else if (Array.isArray(body.rates)) {
  for (const r of body.rates) {
    out.push({
      station_external_id: String(r.station_external_id || r.station_id || ''),
      pole_external_id: String(r.pole_external_id || r.pole_id || ''),
      provider_code: providerCode,
      day_of_week: Number.isInteger(r.day_of_week) ? r.day_of_week : 0,
      hour_start_local: r.hour_start_local || r.hour || '00:00:00',
      price_per_kwh_hkd: String(r.price_per_kwh_hkd ?? r.price ?? 0),
      parking_fee_hkd: String(r.parking_fee_hkd ?? 0),
      valid_from: r.valid_from || new Date().toISOString(),
      valid_to: r.valid_to || null
    });
  }
} else {
  throw new Error('rate-normalize: expected body.poles[] or body.rates[]; got ' + JSON.stringify(body).slice(0, 300));
}

return out.map(item => ({ json: item }));
